"""Measured inventory and routing-role audit for indexed urban data; no inferred counts."""
import csv,gzip,json,pathlib,sqlite3
from datetime import datetime,timezone
ROOT=pathlib.Path(__file__).resolve().parents[1]
import sys;sys.path.insert(0,str(ROOT))
from routing.urban_store import connection,manifest

def build():
 rows=[];crime=manifest('crime');trees=manifest('trees');ctx=manifest('context')
 for s in crime['sources']:
  with connection('crime') as db:n=db.execute('SELECT count(*) FROM incidents WHERE source=?',(s['dataset_id'],)).fetchone()[0]
  rows.append({'dataset_id':s['dataset_id'],'name':s['name'],'source_url':s['url'],'records':n,'source_rows_in_window':s['downloaded_rows'],'source_total_records':s['source_total_records'],'coverage':'NYC five boroughs + unknown source borough','time_range':crime['available_start']+' / '+crime['available_end_exclusive']+' exclusive','publisher_updated_at':s['publisher_updated_at'],'retrieved_at':s['retrieved_at'],'missing_fields':s['missing_fields'],'quality':s['rejected'],'routing_usage':'Independent complaint density: candidate edge costs + exact published-point route corridors + ranking','frontend_usage':'Indexed aggregate density cells; date/offense filters; selected-route corridor','representation':'SQLite R*Tree + daily 200 m grids; no demographic data'})
 rows.append({'dataset_id':trees['dataset_id'],'name':trees['name'],'source_url':trees['source_url'],'records':trees['records'],'source_rows_in_window':trees['source_rows'],'coverage':'NYC five boroughs; published coordinate inventory','time_range':'Current source Full-structure tree inventory; individual update dates vary','publisher_updated_at':trees['publisher_updated_at'],'retrieved_at':trees['retrieved_at'],'missing_fields':trees['missing_fields'],'quality':{'invalid_records':trees['invalid_records'],'duplicate_ids':trees['duplicates'],'dead_condition':trees['conditions'].get('Dead',0),'unknown_condition':trees['conditions'].get('Unknown',0)},'routing_usage':'Queryable independent tree evidence; existing Nature score remains its versioned tree/park snapshot','frontend_usage':'Indexed cells at low zoom, source trees at detail zoom; old/new visual sources do not double draw','representation':'Read-only SQLite R*Tree, 1 MiB page cache per connection'})
 for s in ctx['sources']:
  role='Independent water-proximity edge costs + length-weighted route metrics + ranking' if s['id']=='hydrography' else s.get('routing_usage','Context only; no unverified inference of pedestrian access/closure')
  rows.append({'dataset_id':s['dataset_id'],'name':s['name'],'publisher':s.get('publisher','NYC Open Data'),'license':s.get('license','NYC Open Data Terms of Use'),'license_url':s.get('license_url','https://www.nyc.gov/home/terms-of-use.page'),'source_url':s['source_url'],'records':s['records'],'source_rows_in_window':s['source_rows'],'coverage':s['coverage'],'time_range':s.get('query_scope') or 'Published source snapshot','publisher_updated_at':s['publisher_updated_at'],'retrieved_at':s['retrieved_at'],'missing_fields':s['missing_fields'],'quality':{'invalid_geometries':s['invalid_geometries'],'exact_duplicate_records':s.get('exact_duplicate_records',s.get('exact_duplicate_source_rows',0)),'repeated_legacy_keys':s.get('repeated_original_keys',0)},'routing_usage':role,'frontend_usage':'Indexed viewport/route-corridor query; source inspector + source time','representation':s['crs_transform']+'; indexed geometry fragments for large water polygons'})
 for r in rows:
  r.setdefault('publisher','NYPD / NYC Open Data' if r['dataset_id'] in ('qgea-i56i','5uac-w243') else 'NYC Parks' if r['dataset_id']=='hn5i-inap' else 'NYC Open Data');r.setdefault('license','NYC Open Data Terms of Use');r.setdefault('license_url','https://www.nyc.gov/home/terms-of-use.page')
 out={'built_at':datetime.now(timezone.utc).isoformat(),'datasets':rows,'crime_valid_records':crime['records'],'crime_by_borough':crime['by_borough'],'temporal_quarantine':crime.get('temporal_quarantine_records'),'total_new_source_records':sum(r['records'] for r in rows),'notes':['Source-record totals are not globally unique places.','Historical density is not crime rate; no population or exposure denominator.','Core 12 definitions remain unchanged; crime and water proximity are separate objectives.','Daily occurrence-date analysis; no hour-of-day claim.','No citywide pedestrian graph is claimed: routing remains the verified Manhattan connected network.']}
 target=ROOT/'data/urban/inventory.json';target.write_text(json.dumps(out,indent=2))
 with (ROOT/'URBAN_DATA_INVENTORY.csv').open('w',newline='') as f:
  keys=['dataset_id','name','publisher','license','license_url','source_url','records','source_rows_in_window','coverage','time_range','publisher_updated_at','retrieved_at','missing_fields','quality','routing_usage','frontend_usage','representation'];w=csv.DictWriter(f,fieldnames=keys,extrasaction='ignore',lineterminator='\n');w.writeheader()
  for r in rows:w.writerow({k:json.dumps(v) if isinstance(v,(dict,list)) else v for k,v in r.items()})
 report=['# Urban data expansion and spatial pipeline audit','',f"Generated {out['built_at']}. Counts below are computed from indexed source snapshots; the existing full inventory remains in DATA_AUDIT_REPORT.md and data/registry.json.",'','| Dataset | Retained records | Source URL | Routing role |','|---|---:|---|---|']
 report += [f"| {r['name']} | {r['records']:,} | {r['source_url']} | {r['routing_usage']} |" for r in rows]
 report += ['','## Source quality and exact roles','',f"NYPD retained {crime['records']:,} unique complaint IDs across both sources. Borough counts: {crime['by_borough']}. Rejections: "+str({s['dataset_id']:s['rejected'] for s in crime['sources']})+'. Raw source date ranges include impossible early dates; only the declared interval is ingested. SQL NULL and literal (null) are both counted as missing text. Publisher narrative descriptions still mention 2019; actual row maxima and update timestamps, not that stale prose, establish the data interval. Unknown boroughs remain unknown.',
 '','Crime raw → exact-source point R*Tree and daily 200 m grid counts → graph candidate-search heuristic using 600 m neighbourhoods sampled every <=50 m → physically cell/date-clustered source rows for final de-duplicated complaint counts within 100 m of each real route → reports per route km and a declared nominal strip-area density → monotonic density/(density+fixed graph p95) preference fit → weighted objective utility with unchanged distance penalties. Both high and low search candidates are generated for either preference, so tests compare the same candidate geometries. No hard clipping at p95. No personal-risk prediction.',
 '','Official hydrography polygons → <=25 m samples along graph geometries → share within 100 m of mapped water → candidate costs and final traversed-length-weighted proximity. Water includes rivers, coastal water and lakes; this is not viewshed analysis or proof of a public waterfront entrance. Display polygons are clipped to 2 km fragments and simplified by 2 m; routing uses the original geometry.',
 '','Forestry current Full-structure inventory is queryable across NYC and displayed by zoom. It includes 11,703 Dead and 4,401 Unknown condition records; Full does not mean living. The misleading Living label was corrected to Full-structure inventory trees while keeping all feature geometries, indicators and 12 numeric scores unchanged. Source species/condition/update/DBH are not canopy shade. New tree-index evidence does not silently replace the versioned Nature scoring method or pretend that its planting-date missingness is zero. Exact missing fractions are in inventory.json.',
 '','Construction WKT is transformed from NYC State Plane EPSG:2263 to WGS84 and checked against NYC bounds. Only permits whose work-date interval includes build day are retained. A full roadway closure permit may operate for part of its date interval and does not establish that the sidewalk is blocked. These records are context, not automatic pedestrian-network closures.',
 '','## Existing downloaded data versus routing usage','',
 'Existing building footprints, PLUTO land use/building ages and many street-furniture/transit datasets are legitimate map context, but they do not all enter core experience scores. Architecture currently uses landmark proximity; building age, landmark status and architectural style are not interchangeable. Explore continues to show the original 13 views. Full runtime wiring is verified by route tests, not merely file existence. The new crime/water criteria have independent metrics and explanations instead of being smuggled into Access & Safety or Scenic & Visual.',
 '','## Bounded infrastructure','',
 'Raw large inventories are streamed offline into SQLite and shipped compressed. Runtime streams decompression to a versioned temporary file, verifies the hash and uses read-only immutable SQLite with 1 MiB page cache and mmap disabled. R*Trees and date/type indexes bound queries; the API never downloads an NYC dataset during routing. Crime edge fields use a four-entry cache and a single-flight build lock. Exact corridor metrics have a separate bounded 64-entry cache keyed by source hash, geometry, distance and all time/type filters; direction is excluded because counts do not depend on preference direction. Map queries sum complete daily cells instead of random source row lookups. Full scored route objects are returned to the client and are not retained server-side; only navigation geometry is cached, bounded to 4 MiB/200 entries. Indexed files and the default complaint field are prepared before the service accepts traffic, so source decompression is not charged to the first user route request. Segment Inspector uses a small indexed view, while source-hash validation prevents stale derived fields. All indices are derived from real source records.',
 '','## Menu evidence','',
 'Real first-party menu-verifier receipts for Bagel/Cappuccino at the indexed Bagel Pub and Zucker’s Bagels & Smoked Fish, plus Coffee at Zucker’s, are included with official URL and checked time. The exact receipt list and timestamps are in data/menus/verified-items.json. They seed evidence for at most 12 hours and never imply current stock, branch availability or verified USD pricing. One verified venue may fulfil both dishes as one waypoint; every required item is checked independently. Unverified extra items fail. Expired corpus entries trigger live verification rather than permanent success.',
 '','## Research and remaining gaps','',
 'The official NYC catalog was actively searched for shoreline/hydrography, canopy, bus stops, closures, sidewalk sheds, public art, GTFS, greenways, traffic volume, ramps, museums and hotels. A separate source-discovery receipt records IDs, publishers, update dates and source descriptions. 2015 Street Tree Census was compared with the newer Parks inventory; the newer inventory was selected for current lookup, not mislabelled as measured shade. Building footprints and PLUTO metadata were rechecked; no unverified architectural-style classification is added.',
 '','MTA station/entrance metadata on data.ny.gov returned proxy CONNECT 403, not an origin authentication error. Required MTA/NOAA domains and the tested offline Shapely dependency were saved in the cloud environment draft; the draft still requires user publication and does not prove runtime access. A normal CI ETL runner then retrieved the complete official MTA station (496), entrance (2,120) and Current Bus Stops (23,218 route-stop rows) datasets. Exact publisher bus IDs/coordinates group these into 13,735 stops with route lists and validity intervals. They now have indexed, bounded map queries and explicit source dates; existing Transit Connectivity score values remain unchanged. Partial historic and ridership samples were excluded from the runtime release. Current station coverage includes all five boroughs; ADA flags are not current elevator status. NOAA/NWS point metadata and 156 hourly forecast periods were also successfully checked; existing Open-Meteo forecasts and NWS alerts remain in place. Live MTA alerts/full GTFS timetable integration, full five-borough routing, canopy/solar exposure, live business ratings/room availability, verified current admission prices and proven wheelchair connectivity remain incomplete. These gaps are reported after actual source discovery and ingestion attempts, not used as a substitute for this release.',
 '','## Performance and production receipts','',
 'Before/after process memory, latency, concurrency, map inspection and actual production inputs/results are recorded separately in the release acceptance report and PR. A local result is not a Render result; mocks and recorded menu replays are not live API tests. No production-deployment success is claimed by this generated data audit alone.']
 (ROOT/'URBAN_DATA_EXPANSION_REPORT.md').write_text('\n'.join(report)+'\n');print('Urban audit',len(rows),'datasets',out['total_new_source_records'],'source records')
if __name__=='__main__':build()
